-- Bottles: a State, and a Level while open (ADR-0007).
--
-- Generated by `drizzle-kit generate` from `db/schema.ts`, then finished by hand with the
-- comments and the one trigger a check cannot be: a finished Bottle is never deleted.

CREATE TABLE "bottles" (
	"id" text PRIMARY KEY DEFAULT gen_prefixed_id('btl') NOT NULL,
	"vintage_id" text NOT NULL,
	"state" text DEFAULT 'closed' NOT NULL,
	"level" text,
	"bought_on" date,
	"price" numeric(10, 2),
	"bought_where" text,
	"opened_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "bottles_id_is_prefixed" CHECK ("bottles"."id" ~ '^btl_[a-z0-9]+(_[a-z0-9]+)*$'),
	CONSTRAINT "bottles_state_is_known" CHECK ("bottles"."state" in ('closed', 'open', 'finished')),
	CONSTRAINT "bottles_level_is_known" CHECK ("bottles"."level" in ('full', '3/4', '1/2', '1/4')),
	CONSTRAINT "bottles_level_only_when_open" CHECK (("bottles"."state" = 'open') = ("bottles"."level" is not null)),
	CONSTRAINT "bottles_dates_follow_the_state" CHECK (case "bottles"."state"
            when 'closed' then "bottles"."opened_at" is null and "bottles"."finished_at" is null
            when 'open' then "bottles"."opened_at" is not null and "bottles"."finished_at" is null
            else "bottles"."opened_at" is not null and "bottles"."finished_at" is not null
          end),
	CONSTRAINT "bottles_finished_after_opened" CHECK ("bottles"."finished_at" is null or "bottles"."finished_at" >= "bottles"."opened_at"),
	CONSTRAINT "bottles_price_is_not_negative" CHECK ("bottles"."price" is null or "bottles"."price" >= 0),
	CONSTRAINT "bottles_bought_where_is_not_blank" CHECK ("bottles"."bought_where" is null or ("bottles"."bought_where" = btrim("bottles"."bought_where") and "bottles"."bought_where" <> ''))
);
--> statement-breakpoint
ALTER TABLE "bottles" ADD CONSTRAINT "bottles_vintage_exists" FOREIGN KEY ("vintage_id") REFERENCES "public"."vintages"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "bottles_vintage_id_idx" ON "bottles" USING btree ("vintage_id");

--> statement-breakpoint
comment on table bottles is
  'One physical bottle the owner has had in the house. The Cellar is the ones not finished (ADR-0007).';
--> statement-breakpoint
comment on column bottles.state is
  'closed, open or finished. A finished Bottle is kept: it is history.';
--> statement-breakpoint
comment on column bottles.level is
  'How much is left of an open Bottle, by eye: full, 3/4, 1/2, 1/4. Only while open; anything finer would be invented (ADR-0007).';
--> statement-breakpoint
comment on column bottles.bought_on is
  'The day it was bought, when the owner said.';
--> statement-breakpoint
comment on column bottles.bought_where is
  'The shop, the winery, the friend: a name the owner reads, not a vocabulary.';
--> statement-breakpoint

-- **A finished Bottle is kept** (CONTEXT.md, ADR-0007). It is what was drunk, and a Cellar
-- that forgot it would forget the history the sommelier reads. A Bottle still closed or open
-- may go, which is how a Bottle added by mistake is taken back.
create function a_finished_bottle_is_kept() returns trigger
language plpgsql
as $$
begin
  if old.state = 'finished' then
    raise exception 'a finished Bottle is kept'
      using errcode = 'restrict_violation',
            constraint = 'bottles_finished_is_kept';
  end if;

  return old;
end;
$$;
--> statement-breakpoint
comment on function a_finished_bottle_is_kept() is
  'A finished Bottle is never deleted: it is history (ADR-0007).';
--> statement-breakpoint
create trigger bottles_finished_is_kept
  before delete on bottles
  for each row execute function a_finished_bottle_is_kept();
